extends Node

## Maximum number of distinct item types this inventory can hold.
@export var max_slots: int = 8

## Internal storage: maps item_id (StringName) -> quantity (int).
var _items: Dictionary = {}


func _ready() -> void:
	# Connect to the event bus — inventory reacts to pickup and use events
	# without being directly referenced by Pickup or any other scene.
	EventBus.item_picked_up.connect(_on_item_picked_up)
	EventBus.item_used.connect(_on_item_used)


## Called when EventBus emits item_picked_up.
## Refuses to add a brand-new item type when the inventory is already full.
func _on_item_picked_up(item_id: StringName, quantity: int) -> void:
	if not _items.has(item_id):
		# Would occupy a new slot — check capacity first.
		if _items.size() >= max_slots:
			EventBus.inventory_full.emit()
			return
		_items[item_id] = 0

	_items[item_id] += quantity
	EventBus.inventory_changed.emit(_items.duplicate())


## Called when EventBus emits item_used.
## Decrements quantity by 1; removes the entry when it reaches zero.
func _on_item_used(item_id: StringName) -> void:
	if not _items.has(item_id):
		return

	_items[item_id] -= 1
	if _items[item_id] <= 0:
		_items.erase(item_id)

	EventBus.inventory_changed.emit(_items.duplicate())

extends Area2D

## The identifier of the item this pickup represents.
@export var item_id: StringName = &""

## How many units of the item are granted on pickup.
@export var quantity: int = 1


func _ready() -> void:
	body_entered.connect(_on_body_entered)


## Fires the bus event and removes this node when a player body overlaps.
func _on_body_entered(body: Node) -> void:
	if body.is_in_group("player"):
		EventBus.item_picked_up.emit(item_id, quantity)
		queue_free()

extends Control

## Mirrors the max_slots value from Inventory so the Hotbar knows how many
## Label children to manage. Must match the Inventory node's setting.
@export var max_slots: int = 8

## Ordered list of slot Label nodes (populated in _ready from children).
var _slot_labels: Array[Label] = []


func _ready() -> void:
	# Collect every direct Label child into the ordered slot list.
	for child in get_children():
		if child is Label:
			_slot_labels.append(child)
			child.hide()

	EventBus.inventory_changed.connect(_on_inventory_changed)


## Receives a snapshot Dictionary { item_id -> quantity } from the bus
## and redraws all slot labels.
func _on_inventory_changed(snapshot: Dictionary) -> void:
	# Build a stable ordered list of entries so slot positions are consistent.
	var entries: Array = []
	for item_id in snapshot:
		entries.append([item_id, snapshot[item_id]])

	for i in range(_slot_labels.size()):
		var label: Label = _slot_labels[i]
		if i < entries.size():
			var item_id: StringName = entries[i][0]
			var qty: int           = entries[i][1]
			label.text = "%s x%d" % [item_id, qty]
			label.show()
		else:
			label.text = ""
			label.hide()

